package com.pratik.imagetap;
import android.accessibilityservice.*;import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.time.Duration;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class AutoTapUi73Test {
 public static class Service extends TapService {int sent;GestureDescription gesture;GestureResultCallback callback;protected boolean sendTapGesture(GestureDescription g,GestureResultCallback c){sent++;gesture=g;callback=c;return true;}}
 Service s;MainActivity a;Context c;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.getSharedPreferences("config",0).edit().putBoolean("tap",true).putBoolean("reduceMotion",true).commit();s=Robolectric.buildService(Service.class).create().get();Release67Test.set(s,"prefs",s.getSharedPreferences("config",0));Release67Test.set(s,"wm",s.getSystemService(Context.WINDOW_SERVICE));TapService.instance=s;}
 @After public void cleanup(){if(a!=null)a.finish();s.stopSession("test");s.onDestroy();TapService.instance=null;}
 AutoTapOverlay overlay()throws Exception{return(AutoTapOverlay)Release67Test.get(s,"autoTap");}
 @Test public void homeAndDrawerExposeDedicatedSection()throws Exception{a=Robolectric.buildActivity(MainActivity.class).setup().get();View root=Release67Test.root(a);assertNotNull(AutoBashUiTest.find(root,"Auto Tap"));Release67Test.tab(a,5);assertNotNull(AutoBashUiTest.find(Release67Test.root(a),"Open Auto Tap controls"));assertNotNull(AutoBashUiTest.find(Release67Test.root(a),"Test taps on this phone"));AutoBashUiTest.save(Release67Test.root(a),"auto-tap-page73",824,1656);}
 @Test public void numberTwoCreatesTwoIndependentDraggableTargets()throws Exception{AutoTapPlan p=new AutoTapPlan();p.count(2);AutoTapStore.save(c,p);assertTrue(s.openAutoTap(false));AutoTapOverlay o=overlay();assertEquals(2,o.markers.size());assertEquals("1",((TextView)o.markers.get(0)).getText().toString());assertEquals("2",((TextView)o.markers.get(1)).getText().toString());View marker=o.markers.get(1);float before=p.points.get(1).x;for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_MOVE,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(0,10,action,action==MotionEvent.ACTION_DOWN?100:180,200,0);marker.dispatchTouchEvent(e);e.recycle();}assertNotEquals(before,AutoTapStore.load(c).points.get(1).x,.001);AutoBashUiTest.save(o.panel,"auto-tap-popup73",540,660);}
 @Test public void fastestUsesOneMillisecondAndRemovesTouchableMarkers()throws Exception{AutoTapPlan p=new AutoTapPlan();p.hold=1;p.gap=0;p.points.get(0).x=.9f;p.points.get(0).y=.85f;AutoTapStore.save(c,p);s.openAutoTap(false);AutoTapOverlay o=overlay();o.toggle();assertTrue(o.runner.playing);assertTrue(o.markers.isEmpty());Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(81));assertEquals(1,s.sent);assertEquals(1,s.gesture.getStroke(0).getDuration());o.runner.pause("Paused");s.callback.onCompleted(s.gesture);assertEquals(1,o.runner.taps);assertFalse(o.runner.playing);assertEquals(1,o.markers.size());}
 @Test public void targetUnderMenuCannotTapControls()throws Exception{AutoTapPlan p=new AutoTapPlan();p.points.get(0).x=.1f;p.points.get(0).y=.15f;AutoTapStore.save(c,p);s.openAutoTap(false);AutoTapOverlay o=overlay();o.toggle();assertFalse(o.runner.playing);assertTrue(o.runner.message.contains("under the controls"));assertEquals(0,s.sent);}
 @Test public void layoutsRetainCoordinatesTimingAndNames(){AutoTapPlan p=new AutoTapPlan();p.count(2);p.points.get(1).x=.82f;p.points.get(1).hold=80;p.points.get(1).gap=100;AutoTapStore.slot(c,1,"Game layout",p);AutoTapPlan loaded=AutoTapStore.slot(c,1);assertEquals(.82f,loaded.points.get(1).x,0);assertEquals(80,loaded.hold(1));assertEquals(100,loaded.gap(1));assertEquals("Game layout",AutoTapStore.prefs(c).getString("name1",""));loaded.points.get(1).x=.1f;assertEquals(.82f,AutoTapStore.slot(c,1).points.get(1).x,0);}
 @Test public void recoveryRetainsProgressButAlwaysStartsPaused()throws Exception{s.openAutoTap(false);AutoTapOverlay o=overlay();o.runner.taps=91;o.runner.cycles=91;AutoTapStore.progress(c,o.runner,true);s.closeAutoTap(true);assertTrue(AutoTapStore.prefs(c).getBoolean("active",false));s.openAutoTap(true);assertEquals(91,overlay().runner.taps);assertFalse(overlay().runner.playing);assertTrue(overlay().runner.message.contains("Recovered paused"));s.closeAutoTap(false);assertFalse(AutoTapStore.prefs(c).getBoolean("active",true));}
 @Test public void openingAutoTapStopsRecognitionAndOnlyOnePanelExists()throws Exception{Release67Test.set(s,"visionReady",true);s.startSession();assertTrue((Boolean)Release67Test.get(s,"running"));s.openAutoTap(false);assertFalse((Boolean)Release67Test.get(s,"running"));assertNull(Release67Test.get(s,"panel"));AutoTapOverlay first=overlay();s.openAutoTap(false);assertSame(first,overlay());assertFalse(c.getSharedPreferences("config",0).getBoolean("sessionActive",true));}
 @Test public void invalidAndUnknownLayoutsDoNotSilentlyReplaceSavedData(){AutoTapStore.prefs(c).edit().putString("plan","bad-data").commit();try{AutoTapStore.load(c);fail();}catch(IllegalArgumentException expected){}assertEquals("bad-data",AutoTapStore.prefs(c).getString("plan",""));}
 @Test public void testPadCountsActualReceivedTouches()throws Exception{TapTestActivity test=Robolectric.buildActivity(TapTestActivity.class).setup().get();View pad=AutoBashUiTest.find(test.findViewById(android.R.id.content),"TAP TEST PAD\nPlace targets here");assertNotNull(pad);for(int i=0;i<5;i++)for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(0,10,action,20,20,0);pad.dispatchTouchEvent(event);event.recycle();}assertEquals(5,test.taps);test.finish();}

 static <T extends View>T findType(View v,Class<T> type){if(type.isInstance(v))return type.cast(v);if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++){T found=findType(((android.view.ViewGroup)v).getChildAt(i),type);if(found!=null)return found;}return null;}
 @Test public void numberPickerAppliesTwoTargets()throws Exception{
  s.openAutoTap(false);AutoTapOverlay o=overlay();o.numbers.performClick();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();NumberPicker n=findType(d.findViewById(android.R.id.content),NumberPicker.class);assertNotNull(n);n.setValue(2);d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertEquals(2,overlay().markers.size());
 }
 @Test public void fastestPresetClearsIndividualOverrides()throws Exception{
  AutoTapPlan p=new AutoTapPlan();p.points.get(0).hold=200;p.points.get(0).gap=500;AutoTapStore.save(c,p);s.openAutoTap(false);overlay().speed.performClick();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();AutoBashUiTest.find(d.findViewById(android.R.id.content),"Fastest · 1 ms hold / 0 ms gap").performClick();d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertEquals(1,overlay().plan.hold(0));assertEquals(0,overlay().plan.gap(0));
 }
 @Test public void stopRemovesControlsAndLateCallbackCannotRestart()throws Exception{
  AutoTapPlan p=new AutoTapPlan();p.points.get(0).x=.9f;p.points.get(0).y=.9f;AutoTapStore.save(c,p);s.openAutoTap(false);AutoTapOverlay o=overlay();o.toggle();Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(81));assertEquals(1,s.sent);s.closeAutoTap(false);s.callback.onCompleted(s.gesture);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(5));assertEquals(1,s.sent);assertNull(overlay());assertTrue(o.markers.isEmpty());assertNull(o.panel);
 }
 @Test @Config(qualifiers="w640dp-h360dp-xhdpi") public void landscapeKeepsPlayStopAboveScrollableDetails()throws Exception{
  s.openAutoTap(false);AutoTapOverlay o=overlay();AutoBashUiTest.save(o.panel,"auto-tap-landscape73",540,o.panelParams.height);assertNotNull(findType(o.panel,ScrollView.class));assertTrue(o.play.getParent() instanceof LinearLayout);assertTrue(((View)o.play.getParent()).getBottom()<o.panelParams.height);
 }

 @Test public void settingsChangedDuringPendingTapApplyAfterCompletion()throws Exception{
  AutoTapPlan p=new AutoTapPlan();p.points.get(0).x=.9f;p.points.get(0).y=.9f;AutoTapStore.save(c,p);s.openAutoTap(false);AutoTapOverlay o=overlay();o.toggle();Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(81));AutoTapPlan updated=AutoTapStore.load(c);updated.count(2);AutoTapStore.save(c,updated);s.reloadAutoTap();assertTrue(o.runner.pending);s.callback.onCompleted(s.gesture);assertEquals(2,o.plan.points.size());assertFalse(o.runner.playing);assertEquals(2,o.markers.size());
 }

 @Test public void resizedControlsPreserveTargetsAndProgress()throws Exception{
 c.getSharedPreferences("config",0).edit().putInt("advancedPopupSize",75).commit();s.openAutoTap(false);AutoTapOverlay o=overlay();int small=o.panelParams.width;o.runner.taps=42;float x=o.plan.points.get(0).x;c.getSharedPreferences("config",0).edit().putInt("advancedPopupSize",125).commit();s.applyLauncherPreference();assertTrue(o.panelParams.width>small);assertEquals(42,o.runner.taps);assertEquals(x,o.plan.points.get(0).x,0);AutoBashUiTest.save(o.panel,"resized-popup74",o.panelParams.width,o.panelParams.height);
 }
}
